import Foundation

/// The backing resolver for the ``LazyInjected(_:)-(SyncFactory<T>)`` macro.
///
/// You do not create this type directly. It is generated by the `@LazyInjected` macro expansion.
/// Access is thread-safe via an internal lock.
///
/// Which container the dependency resolves in depends on the factory:
///
/// - Sync and sync-throwing factories resolve on the first read of ``wrappedValue``, in
///   whatever `Container.current` is at that read, not the container the owning object was
///   created in. The result is cached for subsequent reads.
/// - Async and async-throwing factories start a `Task` at init. It inherits the creating
///   context, so it resolves in the container current at init. The first read only stores
///   the `Task`. The task is cancelled in `deinit`.
///
/// If the owning object may be first read outside the context that created it (a callback,
/// a SwiftUI `.task`, a detached task), use ``ConstructorInjected(_:)-(SyncFactory<T>)``, or do the
/// first read inside `withContainer(_:operation:)`.
public final class LazyInjectedResolver<Value, Factory: Sendable> {
    let factory: Factory
    let getter: @Sendable () -> Value
    let cleanup: () -> Void
    private let lock = NSRecursiveLock()

    public init(_ factory: Factory, file: String = #file, line: UInt = #line, function: String = #function) where Factory == SyncFactory<Value> {
        getter = { factory(file: file, line: line, function: function) }
        self.factory = factory
        cleanup = { }
    }

    public init<D>(_ factory: Factory, file: String = #file, line: UInt = #line, function: String = #function) where Factory == SyncThrowingFactory<D>, Value == Result<D, any Error> {
        getter = { Result { try factory(file: file, line: line, function: function) } }
        self.factory = factory
        cleanup = { }
    }

    public init<D>(_ factory: Factory, file: String = #file, line: UInt = #line, function: String = #function) where Factory == AsyncFactory<D>, Value == Task<D, Never> {
        let task = Task { await factory(file: file, line: line, function: function) }
        getter = { task }
        self.factory = factory
        cleanup = task.cancel
    }

    public init<D>(_ factory: Factory, file: String = #file, line: UInt = #line, function: String = #function) where Factory == AsyncThrowingFactory<D>, Value == Task<D, any Error> {
        let task = Task { try await factory(file: file, line: line, function: function) }
        getter = { task }
        self.factory = factory
        cleanup = task.cancel
    }

    deinit {
        cleanup()
    }

    private var _wrappedValue: Value?

    /// The resolved dependency value. Resolved on first access, then cached.
    public var wrappedValue: Value {
        get {
            lock.lock()
            defer { lock.unlock() }

            if let _wrappedValue {
                return _wrappedValue
            }

            let dependency = getter()
            _wrappedValue = dependency
            return dependency
        }
    }

    /// The underlying factory, accessible via the `$` prefix on the annotated property.
    public var projectedValue: Factory {
        factory
    }
}
